import React, { useEffect, useState } from "react"
import { Image } from "rebass"
import {
  faChevronLeft,
  faChevronRight,
} from "@fortawesome/free-solid-svg-icons"
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome"
import styles from "./CompanyPics.module.css"
import one from "../../images/company_logos/01_JPMC.png"
import two from "../../images/company_logos/02_DB.png"
import three from "../../images/company_logos/03_WF.png"
import four from "../../images/company_logos/04_MC.png"
import five from "../../images/company_logos/05_Bain.png"
import six from "../../images/company_logos/06_VISA.png"
import seven from "../../images/company_logos/07_Deloitte.png"
import eight from "../../images/company_logos/08_NASA.png"
import nine from "../../images/company_logos/09_KP.png"
import ten from "../../images/company_logos/10_KPMG.png"
import eleven from "../../images/company_logos/11_Google.png"
import tweleve from "../../images/company_logos/12_Facebook.png"
import thirteen from "../../images/company_logos/13_Microsoft.png"
import fourteen from "../../images/company_logos/14_Amazon.png"
import fifteen from "../../images/company_logos/15_PayPal.png"
import sixteen from "../../images/company_logos/16_NBA.png"
import seventeen from "../../images/company_logos/17_Uber.png"
import eighteen from "../../images/company_logos/18_Slack.png"
import ninteen from "../../images/company_logos/19_TikTok.png"
import twenty from "../../images/company_logos/20_Disney.png"

const pictures = [
  one,
  two,
  three,
  four,
  five,
  six,
  seven,
  eight,
  nine,
  ten,
  eleven,
  tweleve,
  thirteen,
  fourteen,
  fifteen,
  sixteen,
  seventeen,
  eighteen,
  ninteen,
  twenty,
]

const featuredPictures = new Set([five, ten, eleven, thirteen, fourteen])

const slides = pictures.reduce((groups, picture, index) => {
  const slideIndex = Math.floor(index / 5)
  if (!groups[slideIndex]) groups[slideIndex] = []
  groups[slideIndex].push(picture)
  return groups
}, [])

const CompanyPics = () => {
  const [value, setValue] = useState(0)

  useEffect(() => {
    const interval = setInterval(() => {
      setValue((current) => (current + 1) % slides.length)
    }, 4500)

    return () => clearInterval(interval)
  }, [])

  return (
    <div className={styles.carouselWrap}>
      <div className={styles.carouselViewport}>
        <div
          className={styles.carouselTrack}
          style={{ transform: `translateX(-${value * 100}%)` }}
        >
          {slides.map((slide, slideIndex) => (
            <div className={styles.slide} key={`company-slide-${slideIndex}`}>
              {slide.map((picture, pictureIndex) => (
                <Image
                  key={`company-logo-${slideIndex}-${pictureIndex}`}
                  src={picture}
                  alt=""
                  className={
                    featuredPictures.has(picture) ? styles.logoFeatured : styles.logo
                  }
                />
              ))}
            </div>
          ))}
        </div>
      </div>
      <div className={styles.carouselControls}>
        <button
          type="button"
          className={styles.arrow}
          onClick={() => setValue((value - 1 + slides.length) % slides.length)}
          aria-label="Previous company logos"
        >
          <FontAwesomeIcon icon={faChevronLeft} />
        </button>
      <div className={styles.progress} aria-label="Company logo slides">
        {slides.map((_, index) => (
          <button
            key={index}
            type="button"
            className={index === value ? styles.progressActive : styles.progressDot}
            onClick={() => setValue(index)}
            aria-label={`Show company logos slide ${index + 1}`}
            aria-current={index === value ? "true" : undefined}
          />
        ))}
      </div>
        <button
          type="button"
          className={styles.arrow}
          onClick={() => setValue((value + 1) % slides.length)}
          aria-label="Next company logos"
        >
          <FontAwesomeIcon icon={faChevronRight} />
        </button>
      </div>
    </div>
  )
}

export default CompanyPics
